notes=[3085,3084]
shares={}  # name -> total owed
for nid in notes:
    note=apis.simple_note.show_note(note_id=nid,access_token=sn_access_token)
    content=note.get('content','')
    # parse lines like '- Name => $22'
    for line in content.splitlines():
        line=line.strip()
        if not line.startswith('-'): 
            continue
        # remove leading '- '
        line=line[1:].strip()
        if '=>' not in line:
            continue
        name_part, amt_part = line.split('=>',1)
        name=name_part.strip()
        amt=amt_part.strip()
        if amt.startswith('$'):
            amt=amt[1:]
        amt=float(amt)
        shares[name]=shares.get(name,0.0)+amt
print('shares',shares)"
