date_str = now_info['date']
# Convert to YYYY-MM-DD
dt = datetime.strptime(date_str, '%A, %B %d, %Y')
yesterday = (dt - timedelta(days=1)).date().isoformat()
tomorrow = (dt + timedelta(days=1)).date().isoformat()
print('yesterday', yesterday, 'tomorrow', tomorrow)

# Login venmo
email='cod.smith@gmail.com'
venmo_pass=[x['password'] for x in apis.supervisor.show_account_passwords() if x['account_name']=='venmo'][0]
venmo_login=apis.venmo.login(username=email,password=venmo_pass)
venmo_token=venmo_login['access_token']
print('venmo_token_prefix', venmo_token[:15])

# Pull received transactions around yesterday
shares={'Grant': 22.0, 'Sabrina': 60.0, 'Allison': 37.0, 'Sandra': 37.0, 'Kayla': 20.0, 'Stephen': 20.0, 'Jamie': 15.0, 'Anita': 23.0, 'Travis': 39.0}

# normalization helper
import re

def norm(s):
    return re.sub(r'[^a-z0-9]+','', str(s).lower())

shares_norm={k:norm(k) for k in shares}
paid_by={k:0.0 for k in shares}

page_index=0
all_tx=[]
while True:
    tx=apis.venmo.show_transactions(access_token=venmo_token, direction='received', min_created_at=yesterday, max_created_at=tomorrow, page_index=page_index, page_limit=20)
    print('tx_page', page_index, 'count', len(tx) if tx else 0)
    if not tx:
        break
    all_tx.extend(tx)
    page_index+=1

print('total_received_tx', len(all_tx))
# Map transactions to coworkers by sender name
for t in all_tx:
    sender=t.get('sender',{})
    sname=sender.get('name','')
    s_norm=norm(sname)
    matched=None
    for k,kn in shares_norm.items():
        if kn and (kn==s_norm or kn in s_norm or s_norm in kn):
            matched=k
            break
